package org.opensourcepingpong.organization;
import java.util.*; import org.opensourcepingpong.common.api.BusinessException; import org.springframework.http.HttpStatus; import org.springframework.stereotype.Service;
@Service public class AuthorizationService { private final UserOrganizationRoleRepository roles; public AuthorizationService(UserOrganizationRoleRepository roles){this.roles=roles;} public Set<RoleCode> roles(UUID user){return roles.activeCodes(user);} public void require(UUID user,Permission permission){Set<RoleCode> rs=roles(user);boolean manager=rs.stream().anyMatch(r->r==RoleCode.VICE_MINISTER||r==RoleCode.MINISTER||r==RoleCode.VICE_PRESIDENT||r==RoleCode.PRESIDENT||r==RoleCode.ADVISOR);boolean allow=switch(permission){case ROLE_MANAGE->rs.contains(RoleCode.PRESIDENT)||rs.contains(RoleCode.ADVISOR); default->manager;};if(!allow)throw new BusinessException(HttpStatus.FORBIDDEN,"PERMISSION_DENIED","无权执行该操作");}}
